<?php
namespace App\Http\Controllers;use App\Models\{Group,UploadBatch,UploadBatchFile};use App\Services\Media\QueuedMediaIngestor;use Illuminate\Http\{Request,UploadedFile};use Illuminate\Support\Facades\{Gate,Validator};use Illuminate\Support\Str;
class QueuedUploadController extends Controller {public function store(Request $request,Group $group,QueuedMediaIngestor $ingestor){Gate::authorize('upload',$group);$files=$this->files($request->allFiles());$validator=Validator::make(['photos'=>$files],['photos'=>'required|array|max:20','photos.*'=>'image|mimes:jpeg,jpg,png,webp|max:51200']);if($validator->fails())return response()->json(['message'=>$validator->errors()->first()],422);$user=$request->user();$limit=(int)($user->plan_limits['storage_mb']??0)*1024*1024;$incoming=array_sum(array_map(fn($f)=>(int)$f->getSize(),$files));$photoLimit=(int)($user->plan_limits['photos_per_group']??0);if(($limit>0&&(int)$user->storage_used+$incoming>$limit)||($photoLimit>0&&$group->photos()->count()+count($files)>$photoLimit)){$message='You have reached your current plan limit.';return $request->wantsJson()?response()->json(['message'=>$message],422):back()->with('error',$message);}$batch=UploadBatch::create(['uuid'=>(string)Str::uuid(),'group_id'=>$group->id,'user_id'=>$request->user()->id,'state'=>'pending','total_files'=>count($files),'pending_files'=>count($files)]);$uploaded=0;foreach($files as $file){$item=UploadBatchFile::create(['upload_batch_id'=>$batch->id,'client_filename'=>basename($file->getClientOriginalName()),'state'=>'pending']);try{$ingestor->ingest($file,$group,$request->user(),$item);$uploaded++;}catch(\Throwable $e){report($e);$item->update(['state'=>'failed','error'=>'Upload validation or storage failed.']);}}$batch->refreshCounts();$payload=['uploaded'=>$uploaded,'batch_uuid'=>$batch->uuid,'state'=>$batch->fresh()->state];return$request->wantsJson()?response()->json($payload):back()->with('success',"$uploaded photo(s) securely stored and queued.");}private function files(array $values):array{$out=[];array_walk_recursive($values,function($v)use(&$out){if($v instanceof UploadedFile)$out[]=$v;});return$out;}}
